LOCK TABLE mission_factory_owner.editor_release_readiness,mission_factory_owner.c464_control,mission_factory_owner.provider_authoring_runtime,mission_factory_owner.provider_authoring_admissions,mission_generic_owner.runtime_policy,mission_generic_owner.provider_policy,mission_generic_owner.flow_runtime_gate IN SHARE ROW EXCLUSIVE MODE;
FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP
 SELECT jsonb_build_object('oid',p.oid,'signature',item->>'signature','owner',pg_get_userbyid(p.proowner),'secdef',p.prosecdef,'volatility',p.provolatile::text,'config',p.proconfig,'language',l.lanname,'acl',p.proacl::text,'source_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid))) INTO actual FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(item->>'signature');
 IF actual IS DISTINCT FROM item THEN RAISE EXCEPTION 'C1266_AGG5_HEADER_CAS_DRIFT %',item->>'signature'; END IF;
END LOOP;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_factory_owner.editor_release_readiness x WHERE singleton)) IS DISTINCT FROM 'e3dda916e8610954273228ddfee250abda9d47d14c2f08cfa9268b45436b9da2' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT readiness'; END IF;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_factory_owner.c464_control x WHERE singleton)) IS DISTINCT FROM 'f0a94177469f0c7ca03e8ec53cc94fc85a79e39a0b52b3249b28a5879db5989c' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT g2'; END IF;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_factory_owner.provider_authoring_runtime x WHERE singleton)) IS DISTINCT FROM 'b8cb3784b286b01c64cd793da191fb8fc32d2ba5358e6b0629b8a97e8022ec43' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT authoring'; END IF;
IF public.combat_v2_sha256((SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.actor_user),'[]'::jsonb) FROM mission_factory_owner.provider_authoring_admissions x WHERE actor_user=ANY(ARRAY['b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid,'f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid]))) IS DISTINCT FROM '3b2cb90b68307158071b5f1d0fa12ec110f5d12fbd5cd06350cb981eb1032a3d' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT admissions'; END IF;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_generic_owner.runtime_policy x WHERE singleton)) IS DISTINCT FROM '14b9b20565c823f180ecebc0a6a86cb51f85b8e8c72f5be60e7e84e0326e2552' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT runtime'; END IF;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_generic_owner.provider_policy x WHERE singleton)) IS DISTINCT FROM '8d4f3f3a71037a5e84b4b60a7ba36b88750c41607fa277d2d5fb718d774a2270' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT provider'; END IF;
IF public.combat_v2_sha256((SELECT to_jsonb(x) FROM mission_generic_owner.flow_runtime_gate x WHERE singleton)) IS DISTINCT FROM '27e5a59b5d6df746fd302db00d1133368d84dc6014c9c6d32373d4fed6d917c8' THEN RAISE EXCEPTION 'C1266_AGG5_CONFIG_CAS_DRIFT flow'; END IF;
IF EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE owner_kind='ai_service' AND closed_at IS NULL) OR EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND closed_at IS NULL) OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND closed_at IS NULL) OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started','uncertain') AND finalized_at IS NULL) THEN RAISE EXCEPTION 'C1266_AGG5_ACTIVITY_NOT_QUIESCENT'; END IF;
END
$agg5$;
COMMIT;
